import json, urllib.request, urllib.error, sys, base64, hashlib, hmac

HOST = "http://localhost:3000"

def req(method, path, data=None, headers=None):
    if headers is None:
        headers = {}
    if data is not None:
        data = json.dumps(data).encode()
    try:
        req = urllib.request.Request(f"{HOST}{path}", data=data, method=method, headers=headers)
        resp = urllib.request.urlopen(req, timeout=5)
        return resp.status, resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()
    except Exception as e:
        return -1, str(e)

def login(user, pw):
    code, body = req("POST", "/login", {"username": user, "password": pw})
    if code != 200:
        return None, body
    data = json.loads(body)
    return data.get("token"), body

